output_text:
[
  {
    "id": "no_cart_single_file_aisle",
    "text": "Carts are prohibited in single-file shelf aisles where the customer is flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "Customers must not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "single_file_shelf_aisle"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "park_at_upper_aisle_mouth",
    "text": "Upon arriving with a cart at the staging point just outside the narrow upper aisle, the customer is obliged to park the cart there before continuing.",
    "abstraction": {
      "state_properties": {
        "wide_cross_aisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "upper_aisle_mouth": {
          "and": [
            "at(6,3)",
            "wide_cross_aisle"
          ]
        }
      },
      "events": {
        "arrive_at_upper_aisle_mouth_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "upper_aisle_mouth"
              }
            ]
          },
          "post": {
            "and": [
              "upper_aisle_mouth",
              "hasCart"
            ]
          }
        },
        "park_cart": {
          "pre": {
            "and": [
              "upper_aisle_mouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "upper_aisle_mouth",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrive_at_upper_aisle_mouth_with_cart",
      "discharge": "park_cart"
    }
  },
  {
    "id": "no_cart_item_access_in_single_file",
    "text": "Shelf interactions in a single-file aisle must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "single_file_shelf_interaction": {
          "pre": {
            "and": [
              "single_file_shelf_aisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_interaction"
        ]
      }
    }
  },
  {
    "id": "no_roaming_without_cart_except_excursion",
    "text": "Customers may move without a cart only in the entrance cart area, the cart-staging point, or the single-file no-cart aisle.",
    "abstraction": {
      "state_properties": {
        "front_cart_area": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "upper_aisle_mouth": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "allowed_no_cart_zone": {
          "or": [
            "front_cart_area",
            "upper_aisle_mouth",
            "single_file_shelf_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "allowed_no_cart_zone"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_after_parking",
    "text": "Whenever a customer parks a cart and continues without it, they are obliged to reclaim a cart before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "reclaim_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart",
      "discharge": "reclaim_cart"
    }
  },
  {
    "id": "use_front_cart_bay",
    "text": "At the start of a shopping trip, the customer is obliged to take a cart from the front cart bay.",
    "abstraction": {
      "state_properties": {
        "front_cart_bay": {
          "and": [
            "at(1,7)",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            }
          ]
        }
      },
      "events": {
        "take_cart_from_front_bay": {
          "pre": {
            "and": [
              "front_cart_bay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_front_bay"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "Customers are prohibited from exiting the store without a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "without_cart"
        ]
      }
    }
  }
]
